protected Integer compute() {
    if (n <= 1) return n;
    RecursiveTask<Integer> left = new Worker(n - 1);
    RecursiveTask<Integer> right = new Worker(n - 2);
    left.fork();
    right.fork(); // Both forked - potential deadlock!
    return left.join() + right.join();
}

