interface VendingState {
    void processPayment(VendingMachine machine);
    void dispenseItem(VendingMachine machine);
}

class IdleState implements VendingState {
    @Override
    public void processPayment(VendingMachine machine) {
        machine.setState(new DispensingState());
    }

    @Override
    public void dispenseItem(VendingMachine machine) {
        throw new IllegalStateException("Pay first");
    }
}

class DispensingState implements VendingState {
    @Override
    public void processPayment(VendingMachine machine) {
        throw new IllegalStateException("Already dispensing");
    }

    @Override
    public void dispenseItem(VendingMachine machine) {
        // no state transition back to Idle
    }
}

abstract class Handler {
    protected Handler next;

    public void setNext(Handler next) {
        this.next = next;
    }

    public void handle(Request request) {
        if (canHandle(request)) {
            process(request);
        } else {
            next.handle(request); // NPE or infinite loop
        }
    }

    protected abstract boolean canHandle(Request request);
    protected abstract void process(Request request);
}

