@Service
public class PaymentService {
    private final Map<String, PaymentResult> idempotencyStore = new ConcurrentHashMap<>();

    public PaymentResult process(String idempotencyKey, PaymentRequest request) {
        PaymentResult cached = idempotencyStore.get(idempotencyKey);
        if (cached != null) return cached;
        PaymentResult result = chargePayment(request);
        idempotencyStore.put(idempotencyKey, result);
        return result;
    }
}

