    }
}

public void createReleaseArchive(String projectPath, String outputPath) throws Exception {
    ProcessBuilder pb = new ProcessBuilder(
        "git", "archive", "HEAD",
        "--output=" + outputPath);
    pb.directory(new File(projectPath));
    Process process = pb.start();
    process.waitFor();
}

ProcessBuilder pb = new ProcessBuilder(
    "git", "diff", "HEAD~1", "HEAD");
pb.directory(new File(projectPath));
Process process = pb.start();
String diff = new String(process.getInputStream().readAllBytes());
String[] lines = diff.split("\n");
for (String line : lines) {
    if (line.startsWith("+")) {
        addedLines.add(line.substring(1));
    }
}

public void undoLastCommit(String projectPath) throws Exception {
    ProcessBuilder pb = new ProcessBuilder(
        "git", "reset", "--hard", "HEAD~1");
    pb.directory(new File(projectPath));
    Process process = pb.start();
    int exitCode = process.waitFor();
    if (exitCode != 0) {
        throw new RuntimeException("Reset failed");
    }
    ProcessBuilder pushPb = new ProcessBuilder(
        "git", "push", "--force", "origin", "main");
    pushPb.directory(new File(projectPath));
    pushPb.start().waitFor();
}

public void cleanWorkingDirectory(String projectPath) throws Exception {
    ProcessBuilder pb = new ProcessBuilder(
        "git", "clean", "-fd");
    pb.directory(new File(projectPath));
    Process process = pb.start();
    int exitCode = process.waitFor();
    if (exitCode != 0) {
        throw new RuntimeException("Clean failed");
    }
}
